style.css:
/* This applies to the entire background of a site */
body {
    background-color: #0b0b0b !important; /* Deep GX Charcoal */
    color: #e0e0e0 !important; /* Soft white text to reduce eye strain */
}

/* This changes links to that iconic GX Red */
a {
    color: #ff3e3e !important; 
    text-shadow: 0 0 5px rgba(255, 62, 62, 0.4); /* Subtle Neon Glow */
}

/* This styles buttons and headers for a sleek look */
button, h1, h2, h3 {
    background-color: #1a1a1a !important;
    border: 1px solid #333 !important;
    border-radius: 4px !important;
}

/* Custom Scrollbar (The GX Signature) */
::-webkit-scrollbar {
    width: 8px;
}
::-webkit-scrollbar-track {
    background: #0b0b0b;
}
::-webkit-scrollbar-thumb {
    background: #ff3e3e; 
    border-radius: 10px;
}
